import os,re,json,collections,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
I1=G['Demo pair 1 input']; O1=G['Demo pair 1 output']
H,W=len(I1),len(I1[0])
ch={(r,c) for r in range(H) for c in range(W) if I1[r][c]==7 and O1[r][c]==3}
fg={(a,b) for a in range(H) for b in range(W) if I1[a][b]==4}
seen=set(); pairs=[]
for p in sorted(fg):
    if p in seen: continue
    for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
        n=(p[0]+dr,p[1]+dc)
        if n in fg:
            pairs.append(tuple(sorted([p,n]))); seen.add(p); seen.add(n); break
print('pairs',len(pairs))
# each changed cell must be adjacent (8-conn) to >=? fg cells? Or lie on the bounding-box perimeter of some fg comp? 
# Try: fg comps orth; for each comp compute its full bbox ring (perimeter); union of rings == ch?
union=set()
for p in pairs:
    rs=[p[0][0],p[1][0]]; cs=[p[0][1],p[1][1]]
    for r in range(max(0,min(rs)-1),min(H-1,max(rs)+1)+1):
        for c in range(max(0,min(cs)-1),min(W-1,max(cs)+1)+1):
            if (r in(min(rs)-1,max(rs)+1)) or (c in(min(cs)-1,max(cs)+1)): union.add((r,c))
print('pair-ring union == ch:',union==ch,len(ch),len(union),len(union^ch))

def f(g):
    H,W=len(g),len(g[0]); o=[r[:] for r in g]; fg={(a,b) for a in range(H) for b in range(W) if g[a][b]==4}
    seen=set()
    for p in sorted(fg):
        if p in seen: continue
        n=None
        for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
            q=(p[0]+dr,p[1]+dc)
            if q in fg: n=q
        if n is None:
            seen.add(p); continue
        seen.add(n)
        rs=[p[0],n[0]]; cs=[p[1],n[1]]
        for x in range(max(0,min(rs)-1),min(H-1,max(rs)+1)+1):
            for y in range(max(0,min(cs)-1),min(W-1,max(cs)+1)+1):
                onbd=(x in(min(rs)-1,max(rs)+1)) or (y in(min(cs)-1,max(cs)+1))
                if onbd and o[x][y]!=4: o[x][y]=3
    return o
print('d1',f(G['Demo pair 1 input'])==G['Demo pair 1 output'],'d2',f(G['Demo pair 2 input'])==G['Demo pair 2 output'])
